        let lookahead_advantage = if next_item_size > 0 {
            (next_item_size as f64 - item_size as f64) / bin_capacity as f64
        } else {
            0.0
        };

        score += 24.0
            + 70.0 * average_fit_pressure
            + 1.5 * fragmentation
            - 35.0 * lookahead_advantage;
