    // useful capacity classes rather than leaving scattered dead space.
    let fill_fraction = (item / capacity).clamp(0.0, 1.0);
    let post_fraction = (post / capacity).clamp(0.0, 1.0);
    let tightness = 1.0 - (post / residual.max(1.0)).clamp(0.0, 1.0);
    score -= 18.0 * tightness * fill_fraction;

    // Harmonic/capacity-class penalties: dead space below the next item or
    // below a quarter of capacity is disproportionately expensive.
