    // A large item should occupy a bin that is nearly empty; a small item is
    // less costly when it leaves a large, flexible remainder.
    let size_class = (item / capacity).clamp(0.0, 1.0);
    score += 10.0 * size_class * (post_fraction * post_fraction);
    score -= 4.0 * (1.0 - size_class) * post_fraction;

    // The final chance to use this fitting bin gets a decisive bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 28.0;
