    // a strong dead-space penalty.  Exact multiples are treated as clean fits.
    let dead_gap_threshold = 10.0_f64.min(0.10 * capacity);
    let unusable_gap = (dead_gap_threshold - post).max(0.0);
    score += 8.0 * unusable_gap * unusable_gap / dead_gap_threshold;

