    // plausible range of future item sizes.
    if post > 0.0 && post < next_item_size.max(1) as f64 {
        score += 3.0 * (next - post).max(0.0);
    }

    // Reward using space efficiently, with a nonlinear preference for tight
    // fits rather than merely minimizing the residual.
    let fill = item / capacity;
    let residual_fraction = residual / capacity;
    score += 4.0 * residual_fraction * residual_fraction;
    score -= 1.5 * fill * fill;

    // Avoid creating a fragmented residual when there are many bins already
    // open.  With few open bins, preserving some flexibility is less costly.
    let pressure = (open / 10.0).min(3.0);
    score += pressure * (post / capacity) * 3.0;

