    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };
    score += progress * (post / capacity) * 5.0;

    // Look-ahead: if the next item cannot fit after this placement, reserve
    // some preference for bins whose remaining space can accommodate it.
    if next_item_size > 0 {
        if post < next {
            score += 4.0;
        } else {
            score -= 1.0;
        }
    }

    // A small global centering term makes otherwise similar candidates
    // favor the bin whose residual is closest to the mean open-bin residual.
    if open > 0.0 {
        let deviation = (post - mean).abs() / capacity;
        score += 0.8 * deviation * deviation;
    }

    // A brand-new empty bin has no immediate dead space, but it should only
    // win when existing candidates are substantially worse.
    if bin_residual == bin_capacity {
        score += 2.0;
        if open > 0.0 {
            score += (open / total_items.max(1) as f64).min(2.0);
        }
